"""Load the worker configuration from config.toml, with environment overrides and validation."""

import os
import sys
from dataclasses import dataclass, field
from pathlib import Path

import toml

DEFAULT_PATHS = [Path("config.toml"), Path.home() / ".config" / "worker" / "config.toml", Path("/etc/worker.toml")]


@dataclass
class QueueConfig:
    url: str
    name: str = "default"
    prefetch: int = 10


@dataclass
class WorkerConfig:
    queue: QueueConfig
    concurrency: int = 4
    log_level: str = "INFO"
    tags: list = field(default_factory=list)


def find_config(explicit=None):
    if explicit:
        return Path(explicit)
    for path in DEFAULT_PATHS:
        if path.is_file():
            return path
    raise FileNotFoundError("no config.toml found in " + ", ".join(map(str, DEFAULT_PATHS)))


def apply_env_overrides(data):
    if "WORKER_QUEUE_URL" in os.environ:
        data.setdefault("queue", {})["url"] = os.environ["WORKER_QUEUE_URL"]
    if "WORKER_CONCURRENCY" in os.environ:
        data["concurrency"] = int(os.environ["WORKER_CONCURRENCY"])
    return data


def load_config(path=None):
    config_path = find_config(path)
    try:
        data = toml.load(config_path)
    except toml.TomlDecodeError as exc:
        raise SystemExit(f"{config_path}: invalid TOML ({exc})")
    data = apply_env_overrides(data)
    if "queue" not in data or "url" not in data["queue"]:
        raise SystemExit(f"{config_path}: [queue] url is required")
    worker = data.get("worker", {})
    return WorkerConfig(
        queue=QueueConfig(**data["queue"]),
        concurrency=data.get("concurrency", worker.get("concurrency", 4)),
        log_level=worker.get("log_level", "INFO").upper(),
        tags=worker.get("tags", []),
    )


if __name__ == "__main__":
    cfg = load_config(sys.argv[1] if len(sys.argv) > 1 else None)
    print(f"queue={cfg.queue.url} ({cfg.queue.name}) concurrency={cfg.concurrency} log={cfg.log_level}")

"""Chequeo de CI: la versión de pyproject.toml tiene que coincidir con el tag de git y tener entrada en el CHANGELOG.

Uso en el pipeline:  python check_version.py --tag "$CI_COMMIT_TAG"
"""

import argparse
import re
import subprocess
import sys
from pathlib import Path

import toml

SEMVER = re.compile(r"^\d+\.\d+\.\d+(?:(a|b|rc)\d+)?$")


def version_del_proyecto(ruta="pyproject.toml"):
    datos = toml.load(ruta)
    if "project" in datos and "version" in datos["project"]:
        return datos["project"]["version"]
    # proyectos viejos que todavía usan poetry
    return datos.get("tool", {}).get("poetry", {}).get("version")


def ultimo_tag():
    salida = subprocess.run(["git", "describe", "--tags", "--abbrev=0"], capture_output=True, text=True)
    return salida.stdout.strip() if salida.returncode == 0 else None


def tiene_entrada_en_changelog(version, ruta=Path("CHANGELOG.md")):
    if not ruta.exists():
        return False
    return any(linea.startswith(f"## {version}") or linea.startswith(f"## [{version}]")
               for linea in ruta.read_text(encoding="utf-8").splitlines())


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--tag", help="tag a comparar (por defecto, el último tag de git)")
    args = parser.parse_args()

    version = version_del_proyecto()
    errores = []
    if not version:
        errores.append("pyproject.toml no tiene versión")
    elif not SEMVER.match(version):
        errores.append(f"la versión {version!r} no es semver")

    tag = (args.tag or ultimo_tag() or "").lstrip("v")
    if version and tag and tag != version:
        errores.append(f"el tag {tag} no coincide con la versión {version}")
    if version and not tiene_entrada_en_changelog(version):
        errores.append(f"falta la entrada '## {version}' en CHANGELOG.md")

    for error in errores:
        print(f"ERROR: {error}", file=sys.stderr)
    if not errores:
        print(f"ok: versión {version}")
    return 1 if errores else 0


if __name__ == "__main__":
    sys.exit(main())

"""Arma el resumen diario de actividad de cada usuario con las horas en su zona horaria.

Los eventos se guardan en UTC; cada usuario tiene su zona en el perfil (p. ej. "America/Argentina/Buenos_Aires").
"""

import json
import logging
import sqlite3
from collections import defaultdict
from datetime import datetime, timedelta

import pytz

log = logging.getLogger("resumen")
ZONA_POR_DEFECTO = "America/Argentina/Buenos_Aires"


def zona_de(nombre):
    try:
        return pytz.timezone(nombre or ZONA_POR_DEFECTO)
    except pytz.UnknownTimeZoneError:
        log.warning("zona desconocida %r, uso %s", nombre, ZONA_POR_DEFECTO)
        return pytz.timezone(ZONA_POR_DEFECTO)


def a_hora_local(ts_utc, zona):
    """ts_utc es un string ISO sin zona, guardado en UTC."""
    dt = pytz.utc.localize(datetime.fromisoformat(ts_utc))
    return dt.astimezone(zona)


def resumen(conn, desde, hasta):
    usuarios = {uid: zona_de(tz) for uid, tz in conn.execute("SELECT id, timezone FROM usuarios")}
    por_usuario = defaultdict(list)
    filas = conn.execute(
        "SELECT usuario_id, tipo, ts FROM eventos WHERE ts >= ? AND ts < ? ORDER BY ts",
        (desde.isoformat(), hasta.isoformat()),
    )
    for usuario_id, tipo, ts in filas:
        zona = usuarios.get(usuario_id, zona_de(None))
        local = a_hora_local(ts, zona)
        por_usuario[usuario_id].append({"tipo": tipo, "hora": local.strftime("%H:%M"), "zona": local.tzname()})
    return por_usuario


def main(db="actividad.db"):
    logging.basicConfig(level=logging.INFO)
    hasta = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    desde = hasta - timedelta(days=1)
    with sqlite3.connect(db) as conn:
        datos = resumen(conn, desde, hasta)
    for usuario_id, eventos in datos.items():
        print(json.dumps({"usuario": usuario_id, "eventos": eventos}, ensure_ascii=False))
    log.info("%d usuarios con actividad", len(datos))


if __name__ == "__main__":
    main()

"""Programa las tareas diarias del cron "a la hora local" de cada sucursal, sin que el cambio de horario las corra.

Las sucursales de Chile y España cambian de horario; las tareas tienen que correr siempre a la misma hora local, así
que se calcula el próximo instante en UTC para cada una.
"""

import json
import sys
from datetime import datetime, time, timedelta

import pytz

SUCURSALES = {
    "santiago": "America/Santiago",
    "madrid": "Europe/Madrid",
    "cordoba": "America/Argentina/Cordoba",
}


def proxima_ejecucion(hora_local, nombre_zona, ahora_utc=None):
    """Próximo instante (en UTC) en que el reloj de la zona marca hora_local."""
    zona = pytz.timezone(nombre_zona)
    ahora_utc = ahora_utc or datetime.now(pytz.utc)
    ahora_local = ahora_utc.astimezone(zona)
    candidato = datetime.combine(ahora_local.date(), hora_local)
    for _ in range(3):
        try:
            local = zona.localize(candidato, is_dst=None)  # avisa si la hora no existe o es ambigua
        except pytz.NonExistentTimeError:
            local = zona.localize(candidato + timedelta(hours=1), is_dst=True)  # se saltea la hora que no existe
        except pytz.AmbiguousTimeError:
            local = zona.localize(candidato, is_dst=False)  # la segunda vez que el reloj marca esa hora
        if local > ahora_utc:
            return local.astimezone(pytz.utc)
        candidato += timedelta(days=1)
    raise RuntimeError("no se encontró la próxima ejecución")


def plan(tareas, ahora_utc=None):
    salida = []
    for tarea in tareas:
        hora = time.fromisoformat(tarea["hora"])
        zona = SUCURSALES[tarea["sucursal"]]
        cuando = proxima_ejecucion(hora, zona, ahora_utc)
        salida.append({**tarea, "proxima_utc": cuando.isoformat(),
                       "offset_local": cuando.astimezone(pytz.timezone(zona)).strftime("%z")})
    return sorted(salida, key=lambda t: t["proxima_utc"])


if __name__ == "__main__":
    tareas = json.load(open(sys.argv[1] if len(sys.argv) > 1 else "tareas.json"))
    json.dump(plan(tareas), sys.stdout, indent=2, ensure_ascii=False)
    print()

"""Unit tests for the GitHub release checker, without hitting the network."""

import unittest

import mock
import requests

API = "https://api.github.com/repos/{repo}/releases/latest"


class ReleaseError(Exception):
    pass


def latest_release(repo, token=None):
    headers = {"Accept": "application/vnd.github+json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    resp = requests.get(API.format(repo=repo), headers=headers, timeout=10)
    if resp.status_code == 404:
        raise ReleaseError(f"{repo} has no releases")
    resp.raise_for_status()
    data = resp.json()
    return data["tag_name"].lstrip("v"), data["published_at"][:10]


def needs_update(repo, installed):
    latest, _ = latest_release(repo)
    return tuple(map(int, latest.split("."))) > tuple(map(int, installed.split(".")))


def fake_response(status=200, payload=None):
    resp = mock.Mock(status_code=status)
    resp.json.return_value = payload or {}
    resp.raise_for_status.side_effect = None if status < 400 else requests.HTTPError(str(status))
